def build_report() -> str:
    toc = ["Abstract", "Project question, motivation and objectives", "Requirements and scope traceability", "Data sources and provenance", "Acquisition, validation and ETL", "Relational model and derived measures", "System architecture and runtime", "Architecture in UML: components and deployment", "Architecture in UML: the data model", "Architecture in UML: the startup sequence", "Attacking index and descriptive analysis", "Prediction target and feature construction", "Temporal evaluation and model diagnostics", "Defensive metrics, match context and xG boundary", "Application and interface", "Verification strategy and results", "Infrastructure measurement protocol", "Growth, memory and storage results", "Results and interpretation", "Risks, limitations and responsible claims", "Project evolution and contribution evidence", "Conclusion", "References", "Reproduction and appendix: command route"]
    body = ['<section class="page cover"><div><div class="kicker">LUISS · Computational Infrastructures for Data Science</div><h1>Calcio<br>Champagne</h1><p class="lede">Project Report<br>A reproducible football-data system: acquisition, analytical modelling, infrastructure measurements and a browser application.</p></div><div class="cover-meta"><b>Author:</b> Atai Keneshbekov · individual portfolio project<br><b>Evidence snapshot:</b> 6 November 2026<br><b>Repository:</b> Calcio-Champagne-prediction-automated-system<br><b>Submission status:</b> technical evidence documented; source-licence and independent-validation items remain open</div></section>']
    body.append('<section class="page"><div class="kicker">Report structure</div><h2>Contents</h2><ol class="toc">' + ''.join(f'<li>{e(name)} <span class="small">· {i+3}</span></li>' for i, name in enumerate(toc)) + '</ol><div class="callout"><b>Reading note.</b> This report follows the formal structure of a course project report. It describes observed repository behavior and dated measurements; planned, descriptive and unresolved items are labeled as such.</div><p>Primary technical records are maintained in README.md and the linked docs/ directory. The report is a concise submission narrative, not a replacement for the code, raw experiment records or source manifest.</p></section>')
    for title, content in PAGES:
        body.append(f'<section class="page"><div class="kicker">Calcio Champagne · Project report</div><h2>{e(title)}</h2>{content}</section>')
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Calcio Champagne — Project Report</title>' + STYLE + '</head><body>' + ''.join(body) + '</body></html>'


def main() -> None:
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(build_report(), encoding="utf-8")
    print(f"Wrote {OUT.relative_to(ROOT)}: cover + contents + {len(PAGES)} report pages")


if __name__ == "__main__":
    main()
